WITH flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM sessions), sessions_sessions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT s.id, s.customer_id, s.device, s.country, s.session_no, (SELECT AVG(t2.balance) FROM accounts t2 WHERE t2.customer_id = s.customer_id) AS avg_account_balance FROM sessions_sessions s;
